// discountCents returns how many cents a percent discount takes off, rounded to the nearest cent.
function discountCents(cents, percent) {
  return Math.floor((cents * percent) / 100);
}

module.exports = { discountCents };
// formatCents turns whole cents into a display string: 1234 -> "12.34", -50 -> "-0.50".
function formatCents(cents) {
  const dollars = Math.floor(cents / 100);
  const rest = cents % 100;
  return `${dollars}.${String(rest).padStart(2, '0')}`;
}

module.exports = { formatCents };
const { toCents } = require('./parse');
const { discountCents } = require('./discount');
const { formatCents } = require('./format');

// invoice builds the printable lines for an order.
// lines: [{ name, price: "19.99", qty }]. Refund lines have a negative price.
// percentOff: a whole-order discount in percent.
function invoice(lines, percentOff = 0) {
  let subtotal = 0;
  const out = lines.map((l) => {
    const cents = toCents(l.price) * l.qty;
    subtotal += cents;
    return `${l.name}: ${formatCents(cents)}`;
  });
  const off = discountCents(subtotal, percentOff);
  if (off) out.push(`Discount: ${formatCents(-off)}`);
  out.push(`Total: ${formatCents(subtotal - off)}`);
  return out;
}

module.exports = { invoice };
// toCents turns a price string like "19.99" or "-0.50" into whole cents.
function toCents(price) {
  return Math.floor(parseFloat(price) * 100);
}

module.exports = { toCents };
const test = require('node:test');
const assert = require('node:assert');
const { invoice } = require('../invoice');

test('totals a simple order', () => {
  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 1 }]), ['Mug: 19.99', 'Total: 19.99']);
});
