input.command:
cat > parse.js <<'EOF'
// toCents turns a price string like "19.99" or "-0.50" into whole cents.
function toCents(price) {
  return Math.round(parseFloat(price) * 100);
}

module.exports = { toCents };
EOF
cat > discount.js <<'EOF'
// discountCents returns how many cents a percent discount takes off, rounded to the nearest cent.
function discountCents(cents, percent) {
  return Math.round((cents * percent) / 100);
}

module.exports = { discountCents };
EOF
cat > format.js <<'EOF'
// formatCents turns whole cents into a display string: 1234 -> "12.34", -50 -> "-0.50".
function formatCents(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const dollars = Math.floor(abs / 100);
  const rest = abs % 100;
  return `${sign}${dollars}.${String(rest).padStart(2, '0')}`;
}

module.exports = { formatCents };
EOF
cat >> test/invoice.test.js <<'EOF'

test('refund lines format with a sign', () => {
  assert.deepStrictEqual(invoice([{ name: 'Refund', price: '-0.50', qty: 1 }]), ['Refund: -0.50', 'Total: -0.50']);
});

test('prices do not lose a cent to float error', () => {
  assert.deepStrictEqual(invoice([{ name: 'X', price: '0.29', qty: 1 }]), ['X: 0.29', 'Total: 0.29']);
});

test('discount rounds to nearest cent', () => {
  assert.deepStrictEqual(invoice([{ name: 'X', price: '0.10', qty: 1 }], 25), ['X: 0.10', 'Discount: -0.03', 'Total: 0.07']);
});
EOF
